// A strict list of all possible content categories.
enum Category {
  POLITICS_GOVERNANCE
  CONFLICT_SECURITY
  BUSINESS_ECONOMY
  TECHNOLOGY
  SCIENCE
  HEALTH_WELLNESS
  ENVIRONMENT_CLIMATE
  SPORTS
  ARTS_CULTURE
  SOCIETY_HUMAN_INTEREST
  OTHER
}

// A strict list of possible job statuses.
enum JobStatus {
  PENDING
  RUNNING
  COMPLETED
  FAILED
}

// Represents a user authenticated via Clerk.
model User {
  id        String        @id // Clerk User ID
  email     String        @unique
  createdAt DateTime      @default(now())
  updatedAt DateTime      @updatedAt

  jobs      AnalysisJob[]
}

// Represents a single analysis request, its status, and its final result.
// This table now serves as your primary data store AND your cache.
model AnalysisJob {
  id          String    @id @default(cuid())
  queueJobId  String?
  status      JobStatus @default(PENDING)
  input       String    @db.Text
  scrapedText String?   @db.Text
  category    Category?
  result      Json?
  createdAt   DateTime  @default(now())
  updatedAt   DateTime  @updatedAt
  userId      String
  user        User      @relation(fields: [userId], references: [id])

  @@index([userId])
  @@index([category])
}

