    if (!storyId || !nodeId || !choiceId || !nextNodeId) {
      res.status(400).json({
        error: "storyId, nodeId, choiceId, and nextNodeId are required",
      });
      return;
    }
    const existing = await progressService.getProgress(user.id, storyId);
    if (!existing) {
