interface CreateInvoiceParams {
  invoiceId: string;
  amount: number;
  currency: string;
  description: string;
  invoicerEmail: string;
  recipientEmail: string;
}

interface PayPalInvoice {
  id: string;
  href: string;
  status: string;
}

class PayPalService {
  private baseUrl: string;
  private webUrl: string;
  private accessToken: string | null = null;
  private tokenExpiry: number = 0;

  constructor() {
    const mode = process.env.PAYPAL_MODE || "sandbox";
    this.baseUrl = mode === "live" 
      ? "https://api-m.paypal.com" 
      : "https://api-m.sandbox.paypal.com";
    this.webUrl = mode === "live"
      ? "https://www.paypal.com"
      : "https://www.sandbox.paypal.com";
  }

  private async fetchWithRetry(
    url: string,
    options: RequestInit,
    retries = 3
  ): Promise<Response> {
    for (let i = 0; i < retries; i++) {
      try {
        const response = await fetch(url, options);
        if (response.ok || response.status < 500) return response;
        console.warn(`PayPal API returned ${response.status}, retrying (${i + 1}/${retries})...`);
      } catch (error) {
        if (i === retries - 1) throw error;
        console.warn(`PayPal API request failed, retrying (${i + 1}/${retries})...`);
      }
      await new Promise(r => setTimeout(r, 1000 * Math.pow(2, i)));
    }
    throw new Error("PayPal API: Max retries exceeded");
  }

  async healthCheck(): Promise<{ ok: boolean; latency: number }> {
    const start = Date.now();
    try {
      await this.getAccessToken();
      return { ok: true, latency: Date.now() - start };
    } catch {
      return { ok: false, latency: Date.now() - start };
    }
  }

  private async getAccessToken(): Promise<string> {
    if (this.accessToken && Date.now() < this.tokenExpiry) {
      return this.accessToken;
    }

    const clientId = process.env.PAYPAL_CLIENT_ID;
    const clientSecret = process.env.PAYPAL_CLIENT_SECRET;

    if (!clientId || !clientSecret) {
      throw new Error("PayPal credentials not configured");
    }

    const auth = Buffer.from(`${clientId}:${clientSecret}`).toString("base64");

    const response = await fetch(`${this.baseUrl}/v1/oauth2/token`, {
      method: "POST",
      headers: {
        "Authorization": `Basic ${auth}`,
        "Content-Type": "application/x-www-form-urlencoded"
      },
      body: "grant_type=client_credentials"
    });

    if (!response.ok) {
      throw new Error(`PayPal auth failed: ${response.statusText}`);
    }

    const data = await response.json() as { access_token: string; expires_in: number };
    this.accessToken = data.access_token;
    this.tokenExpiry = Date.now() + (data.expires_in * 1000) - 60000; 

    return this.accessToken;
  }

  async createInvoice(params: CreateInvoiceParams): Promise<PayPalInvoice> {
    const token = await this.getAccessToken();

    const invoicePayload = {
      detail: {
        invoice_number: params.invoiceId,
        currency_code: params.currency,
        note: params.description,
        payment_term: {
          term_type: "NET_30"
        }
      },
      invoicer: {
        email_address: params.invoicerEmail
      },
      primary_recipients: [
        {
          billing_info: {
            email_address: params.recipientEmail
          }
        }
      ],
      items: [
        {
          name: params.description.substring(0, 100),
          quantity: "1",
          unit_amount: {
            currency_code: params.currency,
            value: params.amount.toFixed(2)
          }
        }
      ]
    };

    const response = await this.fetchWithRetry(`${this.baseUrl}/v2/invoicing/invoices`, {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${token}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify(invoicePayload)
    });

    if (!response.ok) {
      const error = await response.text();
      throw new Error(`PayPal create invoice failed: ${error}`);
    }

    const data = await response.json() as any;

    let id = data.id;
    if (!id && data.href) {
      const parts = data.href.split("/");
      id = parts[parts.length - 1];
    }

    if (!id) {
       throw new Error("Failed to extract invoice ID from PayPal response");
    }

    try {
      const details = await this.getInvoice(id);
      const payerLink = details.detail?.metadata?.recipient_view_url 
        || `${this.webUrl}/invoice/p/${id}`;

      return {
        id,
        href: payerLink,
        status: "DRAFT"
      };
    } catch (error) {
       console.error("Failed to fetch invoice details:", error);
       return {
         id,
         href: `${this.webUrl}/invoice/p/${id}`,
         status: "DRAFT"
       };
    }
  }

  async sendInvoice(paypalInvoiceId: string): Promise<void> {
    const token = await this.getAccessToken();

    const response = await this.fetchWithRetry(
      `${this.baseUrl}/v2/invoicing/invoices/${paypalInvoiceId}/send`,
      {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${token}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          send_to_invoicer: true,
          send_to_recipient: true
        })
      }
    );

    if (!response.ok) {
      const error = await response.text();
      throw new Error(`PayPal send invoice failed: ${error}`);
    }
  }

  async deleteInvoice(paypalInvoiceId: string): Promise<void> {
    const token = await this.getAccessToken();

    const response = await fetch(
      `${this.baseUrl}/v2/invoicing/invoices/${paypalInvoiceId}`,
      {
        method: "DELETE",
        headers: {
          "Authorization": `Bearer ${token}`
        }
      }
    );

    if (!response.ok) {
      if (response.status === 404) return;

      const error = await response.text();
      throw new Error(`PayPal delete invoice failed: ${error}`);
    }
  }

  async cancelInvoice(paypalInvoiceId: string): Promise<void> {
    const token = await this.getAccessToken();

    const response = await fetch(
      `${this.baseUrl}/v2/invoicing/invoices/${paypalInvoiceId}/cancel`,
      {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${token}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          send_to_invoicer: true,
          send_to_recipient: true,
          note: "Invoice cancelled via PayMe Bot"
        })
      }
    );

    if (!response.ok) {
      if (response.status === 404 || response.status === 422) return;

      const error = await response.text();
      throw new Error(`PayPal cancel invoice failed: ${error}`);
    }
  }

  async getInvoice(paypalInvoiceId: string): Promise<any> {
    const token = await this.getAccessToken();

    const response = await fetch(
      `${this.baseUrl}/v2/invoicing/invoices/${paypalInvoiceId}`,
      {
        method: "GET",
        headers: {
          "Authorization": `Bearer ${token}`,
          "Content-Type": "application/json"
        }
      }
    );

    if (!response.ok) {
      const error = await response.text();
      throw new Error(`PayPal get invoice failed: ${error}`);
    }

    return response.json();
  }

  async sendReminder(paypalInvoiceId: string): Promise<void> {
    const token = await this.getAccessToken();

    const response = await this.fetchWithRetry(
      `${this.baseUrl}/v2/invoicing/invoices/${paypalInvoiceId}/remind`,
      {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${token}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          subject: "Payment Reminder",
          note: "This is a friendly reminder that your invoice is awaiting payment.",
          send_to_invoicer: false,
          send_to_recipient: true
        })
      }
    );

    if (!response.ok) {
      const error = await response.text();
      throw new Error(`PayPal send reminder failed: ${error}`);
    }
  }
}

