async function parseBody(response: Response) {
  const text = await response.text();
  if (!text) return undefined;

  try {
    return JSON.parse(text) as unknown;
  } catch {
    return text;
  }
}

async function serverRequest<T>(path: string): Promise<T> {
  const cookie = (await headers()).get("cookie");
  let response: Response;

  try {
    response = await fetch(`${serverApiUrl()}${path}`, {
      cache: "no-store",
      headers: cookie ? { cookie } : undefined,
    });
  } catch {
    throw new ApiError(
      `Cannot reach the API at ${serverApiUrl()}.`,
      0,
      "NETWORK_ERROR",
    );
  }

  const body = await parseBody(response);
  if (!response.ok) throw apiErrorFromResponse(body, response.status);

  return body as T;
}

const getProjectSummaries = cache(() =>
  serverRequest<ApiProject[]>("/projects"),
);
const getProject = cache((projectId: string) =>
  serverRequest<ApiProject>(`/projects/${projectId}`),
);

async function listShows(): Promise<Show[]> {
  const summaries = await getProjectSummaries();
  const projects = await Promise.all(
    summaries.map((project) => getProject(project.id)),
  );

  return projects
    .flatMap((project) =>
      project.series.map((series) => mapApiSeries(project, series)),
    )
    .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
}

async function getShow(showId: string): Promise<Show | null> {
  const summaries = await getProjectSummaries();
  const owner = summaries.find((project) =>
    project.series.some((series) => series.id === showId),
  );
  if (!owner) return null;

  const project = await getProject(owner.id);
  const series = project.series.find((candidate) => candidate.id === showId);
  return series ? mapApiSeries(project, series) : null;
}

async function getEpisode(
  showId: string,
  episodeId: string,
): Promise<{ show: Show; episode: Episode } | null> {
  const show = await getShow(showId);
  const episode = show?.episodes.find(
    (candidate) => candidate.id === episodeId,
  );
  return show && episode ? { show, episode } : null;
}

async function getAccount(): Promise<Account> {
  const response = await serverRequest<{ user: ApiUser }>("/me");
  return {
    id: response.user.id,
    name: response.user.name,
    email: response.user.email,
    plan: "Not configured",
  };
}

