 * Every method is async and returns plain data, exactly as an HTTP client
 * would. Nothing here mutates: this phase has no job queue, so writes are not
 * modelled at all — see `docs/customer-app.md` for what changes when they are.
 */
export const mockStudio = {
  getAccount: async (): Promise<Account> => account,

