"use client";

import { useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Button } from "@repo/ui/components/ui/button";
import { Input } from "@repo/ui/components/ui/input";
import { Field, FieldGroup, FieldLabel } from "@repo/ui/components/ui/field";
import { Separator } from "@repo/ui/components/ui/separator";
import { toast } from "@repo/ui/components/ui/sonner";
import { authClient } from "@/lib/auth-client";

type AuthFormProps = {
  title: string;
  subtitle: string;
  submitLabel: string;
  /** Only shown on sign-up. */
  withName?: boolean;
  footer: { prompt: string; linkLabel: string; href: string };
};

export function AuthForm({
  title,
  subtitle,
  submitLabel,
  withName,
  footer,
}: AuthFormProps) {
  const router = useRouter();
  const [isSubmitting, setIsSubmitting] = useState(false);

  async function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setIsSubmitting(true);

    const data = new FormData(event.currentTarget);
    const email = String(data.get("email") ?? "").trim();
    const password = String(data.get("password") ?? "");
    const name = String(data.get("name") ?? "").trim();

    try {
      const result = withName
        ? await authClient.signUp.email({ name, email, password })
        : await authClient.signIn.email({ email, password });

      if (result.error) {
        toast.error(result.error.message ?? "Authentication failed.");
        return;
      }

      router.replace("/app/shows");
      router.refresh();
    } catch {
      toast.error("The API could not be reached. Try again in a moment.");
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <div>
      <h1 className="font-heading text-3xl tracking-tight">{title}</h1>
      <p className="mt-2 text-sm/relaxed text-muted-foreground text-pretty">
        {subtitle}
      </p>

      <form className="mt-8" onSubmit={submit}>
        <FieldGroup>
          {withName ? (
            <Field>
              <FieldLabel htmlFor="name">Name</FieldLabel>
              <Input
                id="name"
                name="name"
                autoComplete="name"
                placeholder="Meera Rathod"
                required
              />
            </Field>
          ) : null}

          <Field>
            <FieldLabel htmlFor="email">Email</FieldLabel>
            <Input
              id="email"
              name="email"
              type="email"
              autoComplete="email"
              placeholder="you@studio.com"
              required
            />
          </Field>

          <Field>
            <FieldLabel htmlFor="password">Password</FieldLabel>
            <Input
              id="password"
              name="password"
              type="password"
              autoComplete={withName ? "new-password" : "current-password"}
              placeholder="••••••••••"
              minLength={8}
              required
            />
          </Field>

          <Button
            size="lg"
            className="w-full"
            type="submit"
            disabled={isSubmitting}
          >
            {isSubmitting ? "Please wait…" : submitLabel}
          </Button>
        </FieldGroup>
      </form>

      <div className="mt-6 flex items-center gap-3">
        <Separator className="flex-1" />
        <span className="text-xs text-muted-foreground">or</span>
        <Separator className="flex-1" />
      </div>

      <Button
        variant="outline"
        size="lg"
        className="mt-6 w-full"
        disabled
        title="Google sign-in is not configured on the API yet."
      >
        Continue with Google · coming later
      </Button>

      <p className="mt-8 text-sm text-muted-foreground">
        {footer.prompt}{" "}
        <Link
          href={footer.href}
          className="text-foreground underline underline-offset-4 hover:text-primary-soft-foreground"
        >
          {footer.linkLabel}
        </Link>
      </p>
    </div>
  );
}

import express from "express";
import cors from "cors";
import { toNodeHandler } from "better-auth/node";
import { auth } from "./auth";
import { attachSession, requireUser } from "./middleware/session";
import { router as assetsRouter } from "./routes/assets";
import { router as customerRouter } from "./routes/customer";
import { router as generationsRouter } from "./routes/generations";
import { router as pipelineRouter } from "./routes/pipeline";
import { router as episodeMusicRouter } from "./routes/episode-music";
import { router as musicRouter } from "./routes/music";
import { router as projectsRouter } from "./routes/projects";

/**
 * The whole API, minus the `listen`. Kept separate from index.ts so that
 * `tests/ownership/route-guards.test.ts` can walk the real route table and
 * call the real middleware chain — a guard test built against a hand-rolled
 * test app would only ever prove the test app is safe.
 */
export function createApp() {
  const app = express();

  /*
    Sessions are cookies, so every allowed origin has to be named explicitly —
    `credentials: true` and a wildcard are mutually exclusive in the browser.
    An unset CORS_ORIGIN used to mean "open to everyone"; in production that is
    a hole rather than a convenience, so it is now a startup failure.
  */
  const corsOrigins = process.env.CORS_ORIGIN?.split(",")
    .map((origin) => origin.trim())
    .filter(Boolean);

  if (!corsOrigins?.length && process.env.NODE_ENV === "production") {
    throw new Error(
      "CORS_ORIGIN is required in production. Set it to a comma-separated list " +
        "of allowed origins, e.g. https://app.example.com.",
    );
  }

  app.use(
    cors({
      origin: corsOrigins?.length ? corsOrigins : true,
      credentials: true,
    }),
  );

  /*
    Better Auth needs the raw request body, so it is mounted ahead of
    express.json(). Express 5 requires the named-wildcard form of the path.
  */
  app.all("/api/auth/*splat", toNodeHandler(auth));

  app.use(express.json({ limit: "10mb" }));
  app.use(attachSession);

  app.get("/", (_req, res) => {
    res.send("Hello world");
  });

  app.get("/me", requireUser, (req, res) => {
    res.json({ user: req.user });
  });

  app.use("/assets", assetsRouter);
  app.use("/customers", customerRouter);
  app.use("/episodes", pipelineRouter);
  app.use("/episodes", episodeMusicRouter);
  app.use("/music", musicRouter);
  app.use("/generations", generationsRouter);
  app.use("/projects", projectsRouter);

  return app;
}

import type { GenerationJobRow, GenerationStage } from "../jobs";
import { scopeOf } from "../jobs";
import { runCharacterImages } from "./character-images";
import { runDialogueRender } from "./dialogue-render";
import { runEpisodeDirection } from "./episode-direction";
import { runFinalVideo } from "./final-video";
import { runSceneSlides, runSceneStills } from "./scene-images";
import { runSeriesBase } from "./series-base";

export { createPendingSeries } from "./series-base";
export { createPendingEpisode } from "./episode-direction";

/**
 * What one stage does, given the job that asked for it.
 *
 * Whatever it returns is stored on the job as `result` and is the body the
 * synchronous `?wait=1` mode answers with — so a runner returns the same shape
 * its endpoint used to.
 */
export type StageRunner = (ctx: {
  job: GenerationJobRow;
  input: Record<string, unknown>;
}) => Promise<unknown>;

function episodeIdOf(job: GenerationJobRow) {
  const scope = scopeOf(job);

  if (!("episodeId" in scope)) {
    throw new Error(`Stage "${job.stage}" needs an episode, not a show.`);
  }

  return scope.episodeId;
}

function seriesIdOf(job: GenerationJobRow) {
  const scope = scopeOf(job);

  if (!("seriesId" in scope)) {
    throw new Error(`Stage "${job.stage}" needs a show, not an episode.`);
  }

  return scope.seriesId;
}

/**
 * The seven stages, keyed by the enum. Typed as a total `Record`, so a stage
 * added to `GenerationStage` without an implementation is a build error rather
 * than a job that queues and never drains.
 */
export const STAGE_RUNNERS: Record<
  NonNullable<GenerationStage>,
  StageRunner
> = {
  series_base: ({ job, input }) =>
    runSeriesBase({ seriesId: seriesIdOf(job), input }),
  character_images: ({ job, input }) =>
    runCharacterImages({ seriesId: seriesIdOf(job), input }),
  episode_direction: ({ job, input }) =>
    runEpisodeDirection({ jobId: job.id, episodeId: episodeIdOf(job), input }),
  scene_stills: ({ job, input }) =>
    runSceneStills({ episodeId: episodeIdOf(job), input }),
  scene_slides: ({ job, input }) =>
    runSceneSlides({ episodeId: episodeIdOf(job), input }),
  dialogue_render: ({ job, input }) =>
    runDialogueRender({ episodeId: episodeIdOf(job), input }),
  final_video: ({ job, input }) =>
    runFinalVideo({ episodeId: episodeIdOf(job), input }),
};

import { createApp } from "./app";
import { startGenerationWorker } from "./generation/worker";
import { startMusicWorker } from "./music/worker";

const app = createApp();
const port = Number(process.env.PORT ?? 3000);

/*
  The drain loop lives here rather than in `createApp()` so that a test can
  build the real app without a background worker racing it for the rows it is
  asserting on. One process, one loop, one job at a time.
*/
const stopWorker = startGenerationWorker();
const stopMusicWorker = startMusicWorker();

const server = app.listen(port, () => {
  console.log(`Server is running on port ${port}`);
});

for (const signal of ["SIGINT", "SIGTERM"] as const) {
  process.on(signal, () => {
    stopWorker();
    stopMusicWorker();
    server.close(() => process.exit(0));
  });
}

