  "fadewhite",
] as const;

export type Transition = (typeof TRANSITIONS)[number];

export function isTransition(value: unknown): value is Transition {
  return (
    typeof value === "string" &&
    (TRANSITIONS as readonly string[]).includes(value)
  );
}

export type SceneInput = {
  /** Local file path to the scene image (already composited with dialogue). */
  imagePath: string;
  /** How long this scene should be on screen, in seconds. */
  durationSeconds: number;
  /** Optional label used only for error messages. */
  sceneNumber?: number;
  /** Per-scene Ken Burns override (e.g. false for a static title card). */
  kenBurns?: boolean;
};

export type RenderEpisodeOptions = {
  scenes: SceneInput[];
  /** Local output path. Extension should be `.mp4`. */
  outputPath: string;
  width: number;
  height: number;
  fps?: number;
  /** Transition between scenes. Default `fade`. */
  transition?: Transition;
  /** Crossfade length in seconds. Default 0.5. Ignored for `cut`. */
  transitionDurationSeconds?: number;
  /** Apply a subtle Ken Burns zoom to each still. Default true. */
  kenBurns?: boolean;
  /** Optional background audio track (looped, trimmed to video length). */
  audioPath?: string;
  /** Background audio volume, 0..1. Default 1. */
  audioVolume?: number;
  /**
   * Start playback from this position in the source track. Default 0. Once the
   * track reaches its end it wraps to the top rather than back to this offset.
   */
  audioStartSeconds?: number;
  /** Fade background audio in and out. Default 0.75 seconds. */
  audioFadeSeconds?: number;
  timeoutMs?: number;
  onProgress?: (line: string) => void;
};

export type RenderEpisodeResult = {
  outputPath: string;
  durationSeconds: number;
  sceneCount: number;
  width: number;
  height: number;
  fps: number;
  transition: Transition;
  hadAudio: boolean;
};

export type NormalizeAudioOptions = {
  inputPath: string;
  outputPath: string;
  timeoutMs?: number;
};

export type NormalizeAudioResult = {
  outputPath: string;
  durationSeconds: number | null;
};

export type ExtractAudioWaveformOptions = {
  inputPath: string;
  columns?: number;
  timeoutMs?: number;
};

const DEFAULT_FPS = 30;
const DEFAULT_TRANSITION_SECONDS = 0.5;
const MIN_SCENE_SECONDS = 0.5;
// Gentle zoom — a large zoom on a still reads as "shaky" once composited.
const KEN_BURNS_MAX_ZOOM = 1.08;
// Supersample the still before zoompan so the crop window moves in sub-pixel
// steps at output resolution; without this the slow zoom visibly jitters.
const KEN_BURNS_SUPERSAMPLE_TARGET = 3840;

function round2(value: number): number {
  return Math.round(value * 100) / 100;
}

function round4(value: number): number {
  return Math.round(value * 10000) / 10000;
}

function durationFromFfmpegOutput(stderr: string): number | null {
  const match = stderr.match(/Duration:\s*(\d{2}):(\d{2}):(\d{2}(?:\.\d+)?)/);
  if (!match) return null;
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  const seconds = Number(match[3]);
  if (![hours, minutes, seconds].every(Number.isFinite)) return null;
  return round2(hours * 3600 + minutes * 60 + seconds);
}

/**
 * Converts an imported track to the catalog's normalized MP3 format. A single
 * loudness pass keeps background tracks consistent without an additional
 * analysis invocation or intermediate output.
 */
export async function normalizeAudioTrack(
  options: NormalizeAudioOptions,
): Promise<NormalizeAudioResult> {
  const result = await runFfmpeg(
    [
      "-y",
      "-hide_banner",
      "-i",
      options.inputPath,
      "-map_metadata",
      "-1",
      "-vn",
      "-af",
      "loudnorm=I=-18:TP=-2:LRA=11",
      "-ar",
      "44100",
      "-ac",
      "2",
      "-c:a",
      "libmp3lame",
      "-b:a",
      "192k",
      options.outputPath,
    ],
    { timeoutMs: options.timeoutMs },
  );

  return {
    outputPath: options.outputPath,
    durationSeconds: durationFromFfmpegOutput(result.stderr),
  };
}

/**
 * Produces a compact, display-ready waveform without retaining decoded audio.
 * The ffmpeg pass downsamples to mono PCM first, then this function reduces it
 * to a fixed number of peak columns that can be stored directly on a track.
 */
export async function extractAudioWaveformPeaks(
  options: ExtractAudioWaveformOptions,
): Promise<number[]> {
  const columns = Math.max(32, Math.min(1_024, options.columns ?? 320));
  const workDir = await mkdtemp(join(tmpdir(), "directorscut-waveform-"));
  const pcmPath = join(workDir, "waveform.pcm");

  try {
    await runFfmpeg(
      [
        "-y",
        "-hide_banner",
        "-i",
        options.inputPath,
        "-vn",
        "-ac",
        "1",
        "-ar",
        "8000",
        "-f",
        "s16le",
        pcmPath,
      ],
      { timeoutMs: options.timeoutMs },
    );

    const pcm = await readFile(pcmPath);
    const sampleCount = Math.floor(pcm.byteLength / 2);
    if (sampleCount === 0) return Array.from({ length: columns }, () => 0);

    const rawPeaks = Array.from({ length: columns }, (_, column) => {
      const start = Math.floor((column * sampleCount) / columns);
      const end = Math.max(
        start + 1,
        Math.floor(((column + 1) * sampleCount) / columns),
      );
      let peak = 0;

      for (
        let sample = start;
        sample < end && sample < sampleCount;
        sample += 1
      ) {
        peak = Math.max(peak, Math.abs(pcm.readInt16LE(sample * 2)) / 32_768);
      }

      return peak;
    });

    const nonSilent = rawPeaks.filter((peak) => peak > 0).sort((a, b) => a - b);
    const reference = nonSilent.length
      ? nonSilent[Math.floor((nonSilent.length - 1) * 0.95)]!
      : 1;

    return rawPeaks.map((peak) =>
      peak === 0
        ? 0
        : Math.round(Math.min(1, Math.sqrt(peak / reference)) * 1_000) / 1_000,
    );
  } finally {
    await rm(workDir, { recursive: true, force: true }).catch(() => {});
  }
}

/**
 * Builds the per-scene video filter. With Ken Burns we cover the frame and
 * slowly zoom in; without it we letterbox the still onto a black frame.
 */
function sceneFilter(params: {
  index: number;
  width: number;
  height: number;
  fps: number;
  durationSeconds: number;
  kenBurns: boolean;
}): string {
  const { index, width, height, fps, durationSeconds, kenBurns } = params;
  const input = `[${index}:v]`;
  const output = `[v${index}]`;

  if (!kenBurns) {
    return (
      `${input}scale=${width}:${height}:force_original_aspect_ratio=decrease,` +
      `pad=${width}:${height}:-1:-1:color=black,setsar=1,fps=${fps},` +
      `format=yuv420p${output}`
    );
  }

  const frames = Math.max(1, Math.round(durationSeconds * fps));
  const step = round4((KEN_BURNS_MAX_ZOOM - 1) / frames);
  // Guard against a zero step (very long scenes) collapsing the animation.
  const zoomStep = step > 0 ? step : 0.0004;

  // Cover the frame at a supersampled size, zoom on that, then downscale to the
  // output. The larger working canvas keeps the slow zoom smooth (no shake).
  const scaleFactor = Math.max(
    2,
    Math.min(
      4,
      Math.floor(KEN_BURNS_SUPERSAMPLE_TARGET / Math.max(width, height)),
    ),
  );
  const superW = width * scaleFactor;
  const superH = height * scaleFactor;

  return (
    `${input}scale=${superW}:${superH}:force_original_aspect_ratio=increase,` +
    `crop=${superW}:${superH},` +
    `zoompan=z='min(zoom+${zoomStep},${KEN_BURNS_MAX_ZOOM})':` +
    `d=${frames}:x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':` +
    `s=${width}x${height}:fps=${fps},setsar=1,format=yuv420p${output}`
  );
}

/**
 * Renders an episode video from a list of scene stills using ffmpeg.
 *
 * Each still becomes a timed segment (optionally with a Ken Burns zoom), the
 * segments are joined with a crossfade (or hard cut), and an optional looped
 * background track is mixed in. The whole thing is a single ffmpeg invocation
 * built from one `filter_complex` graph.
 */
export async function renderEpisodeVideo(
  options: RenderEpisodeOptions,
): Promise<RenderEpisodeResult> {
  const {
    scenes,
    outputPath,
    width,
    height,
    audioPath,
    onProgress,
    timeoutMs,
  } = options;

  if (scenes.length === 0) {
    throw new Error("renderEpisodeVideo requires at least one scene");
  }

  const fps = options.fps ?? DEFAULT_FPS;
  const kenBurns = options.kenBurns ?? true;
  const transition: Transition = options.transition ?? "fade";
  const audioVolume = options.audioVolume ?? 1;
  const audioStartSeconds = Math.max(0, options.audioStartSeconds ?? 0);

  const durations = scenes.map((scene) =>
    Math.max(MIN_SCENE_SECONDS, scene.durationSeconds || MIN_SCENE_SECONDS),
  );

  // Clamp the crossfade so it never exceeds half of the shortest scene, which
  // would make the xfade offset math go negative.
  const shortest = Math.min(...durations);
  const requested =
    options.transitionDurationSeconds ?? DEFAULT_TRANSITION_SECONDS;
  const useCut = transition === "cut" || scenes.length === 1;
  const xfadeDuration = useCut ? 0 : round2(Math.min(requested, shortest / 2));

  const args: string[] = ["-y"];

  // One looping still input per scene.
  for (let i = 0; i < scenes.length; i += 1) {
    args.push(
      "-loop",
      "1",
      "-t",
      String(durations[i]),
      "-i",
      scenes[i]!.imagePath,
    );
  }

  const hadAudio = Boolean(audioPath);
  if (audioPath) {
    // The loop is applied at the demuxer, always from the top of the file. The
    // start offset is taken off the *looped* stream below (see `atrim`) so the
    // track wraps to zero instead of restarting at the offset every iteration.
    args.push("-stream_loop", "-1", "-i", audioPath);
  }

  const filters: string[] = [];
  for (let i = 0; i < scenes.length; i += 1) {
    filters.push(
      sceneFilter({
        index: i,
        width,
        height,
        fps,
        durationSeconds: durations[i]!,
        kenBurns: scenes[i]!.kenBurns ?? kenBurns,
      }),
    );
  }

  let videoOutLabel: string;
  let totalDuration: number;

  if (scenes.length === 1) {
    videoOutLabel = "[v0]";
    totalDuration = durations[0]!;
  } else if (useCut) {
    const inputs = scenes.map((_, i) => `[v${i}]`).join("");
    filters.push(`${inputs}concat=n=${scenes.length}:v=1:a=0[vout]`);
    videoOutLabel = "[vout]";
    totalDuration = durations.reduce((sum, d) => sum + d, 0);
  } else {
    // Chain xfades. offset_m = (sum of the first m scene durations) - m*xfade.
    let prevLabel = "[v0]";
    let cumulative = 0;
    for (let m = 1; m < scenes.length; m += 1) {
      cumulative += durations[m - 1]!;
      const offset = round2(cumulative - m * xfadeDuration);
      const outLabel = m === scenes.length - 1 ? "[vout]" : `[x${m}]`;
      filters.push(
        `${prevLabel}[v${m}]xfade=transition=${transition}:` +
          `duration=${xfadeDuration}:offset=${offset}${outLabel}`,
      );
      prevLabel = outLabel;
    }
    videoOutLabel = "[vout]";
    totalDuration =
      durations.reduce((sum, d) => sum + d, 0) -
      (scenes.length - 1) * xfadeDuration;
  }

  totalDuration = round2(totalDuration);

  args.push("-filter_complex", filters.join(";"));
  args.push("-map", videoOutLabel);

  if (audioPath) {
    const audioInputIndex = scenes.length;
    args.push("-map", `${audioInputIndex}:a`);
    const audioFilters: string[] = [];
    if (audioStartSeconds > 0) {
      // Trimming after `-stream_loop` (rather than seeking with `-ss` before
      // the input) is what makes the offset a *starting point*: the first pass
      // plays offset→end, and every later pass plays the whole track from 0.
      audioFilters.push(
        `atrim=start=${round2(audioStartSeconds)}`,
        "asetpts=PTS-STARTPTS",
      );
    }
    if (audioVolume !== 1) {
      audioFilters.push(`volume=${round2(audioVolume)}`);
    }
    const requestedFade = Math.max(0, options.audioFadeSeconds ?? 0.75);
    const fadeSeconds = round2(Math.min(requestedFade, totalDuration / 2));
    if (fadeSeconds > 0) {
      audioFilters.push(`afade=t=in:st=0:d=${fadeSeconds}`);
      audioFilters.push(
        `afade=t=out:st=${round2(totalDuration - fadeSeconds)}:d=${fadeSeconds}`,
      );
    }
    if (audioFilters.length > 0) {
      args.push("-af", audioFilters.join(","));
    }
    args.push("-c:a", "aac", "-b:a", "192k");
  }

  args.push(
    "-c:v",
    "libx264",
    "-preset",
    "veryfast",
    "-crf",
    "20",
    "-pix_fmt",
    "yuv420p",
    "-r",
    String(fps),
    "-t",
    String(totalDuration),
    "-movflags",
    "+faststart",
    outputPath,
  );

  await runFfmpeg(args, {
    timeoutMs,
    onStderr: onProgress
      ? (chunk) => {
          for (const line of chunk.split(/\r?\n/)) {
            if (line.trim()) onProgress(line.trim());
          }
        }
      : undefined,
  });

  return {
    outputPath,
    durationSeconds: totalDuration,
    sceneCount: scenes.length,
    width,
    height,
    fps,
    transition: useCut ? "cut" : transition,
    hadAudio,
  };
}

import type {
  Category,
  Episode,
  FinalVideoResult,
  Orientation,
  Project,
  Series,
} from "./types";

export const API_URL =
  process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:3000";

export class ApiError extends Error {
  status: number;
  constructor(message: string, status: number) {
    super(message);
    this.status = status;
    this.name = "ApiError";
  }
}

/**
 * The API answers `{ error: { code, message } }`. Better Auth's own routes
 * answer `{ message, code }` at the top level, and a couple of older handlers
 * still answer `{ error: "…" }` — all three read the same way here rather than
 * stringifying an object into "[object Object]".
 */
function errorMessage(data: unknown): string | undefined {
  if (!data || typeof data !== "object") return undefined;

  const { error, message } = data as { error?: unknown; message?: unknown };

  if (error && typeof error === "object" && "message" in error) {
    return String((error as { message: unknown }).message);
  }
  if (typeof error === "string") return error;
  if (typeof message === "string") return message;

  return undefined;
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let response: Response;
  try {
    response = await fetch(`${API_URL}${path}`, {
      ...init,
      /*
        Every route below now needs the Better Auth session cookie, and the API
        is a different origin (3000 vs 3001), so it is not sent by default.
        The matching half is CORS_ORIGIN + credentials: true on the server.
      */
      credentials: "include",
      headers: {
        "Content-Type": "application/json",
        ...(init?.headers ?? {}),
      },
    });
  } catch {
    throw new ApiError(
      `Cannot reach the API at ${API_URL}. Is the server running?`,
      0,
    );
  }

  if (response.status === 204) return undefined as T;

  const text = await response.text();
  const data = text ? JSON.parse(text) : undefined;

  if (!response.ok) {
    throw new ApiError(
      errorMessage(data) ?? `Request failed (${response.status})`,
      response.status,
    );
  }

  return data as T;
}

const G = "/generations/static-image-video";

/*
  The seven pipeline stages are queued now: their endpoints answer 202 with a
  job row and the worker drains it. The playground is a stepper — press a
  button, look at what came back — and has no rail to watch a job on, so it
  keeps the old synchronous behaviour by asking for it explicitly. `?wait=1`
  runs the stage inside the request and answers with exactly the body these
  calls already expect. See docs/generation-jobs.md.
*/
const WAIT = "?wait=1";

export const api = {
  // Projects
  listProjects: () => request<Project[]>("/projects"),
  getProject: (id: string) => request<Project>(`/projects/${id}`),
  createProject: (body: {
    projectName: string;
    email: string;
    name?: string;
    description?: string;
  }) =>
    request<Project>("/projects", {
      method: "POST",
      body: JSON.stringify(body),
    }),
  deleteProject: (id: string) =>
    request<void>(`/projects/${id}`, { method: "DELETE" }),

  // Assets
  presign: (key: string) =>
    request<{ key: string; url: string }>(
      `/assets/presign?key=${encodeURIComponent(key)}`,
    ),

  // Series (bible) + episodes
  createSeriesBase: (
    projectId: string,
    body: {
      storyIdea: string;
      category?: Category;
      orientation?: Orientation;
      visualDirection?: string;
      characterDirection?: string;
      dialogueDirection?: string;
      musicDirection?: string;
    },
  ) =>
    request<{ series: Series; base: unknown }>(
      `/generations/projects/${projectId}/static-image-video/base${WAIT}`,
      { method: "POST", body: JSON.stringify(body) },
    ),

  generateEpisode: (
    seriesId: string,
    body: { episodeIdea?: string; targetSceneCount?: number },
  ) =>
    request<{ episode: Episode }>(`${G}/series/${seriesId}/episode${WAIT}`, {
      method: "POST",
      body: JSON.stringify(body),
    }),

  getEpisodeStory: (episodeId: string) =>
    request<unknown>(`${G}/episodes/${episodeId}/story`),

  generateCharacterImages: (seriesId: string) =>
    request<{
      assetUrls: Record<string, string>;
      skippedCharacterIds: string[];
    }>(`${G}/series/${seriesId}/characters/images${WAIT}`, {
      method: "POST",
      body: JSON.stringify({}),
    }),

  generateStills: (episodeId: string) =>
    request<{ assetUrls: Record<string, string> }>(
      `${G}/episodes/${episodeId}/scenes/stills${WAIT}`,
      { method: "POST", body: JSON.stringify({}) },
    ),

  generateSlides: (episodeId: string) =>
    request<{ slideUrls: Record<string, string> }>(
      `${G}/episodes/${episodeId}/scenes/slides${WAIT}`,
      { method: "POST", body: JSON.stringify({}) },
    ),

  renderDialogueSlides: (
    episodeId: string,
    body: Record<string, unknown> = {},
  ) =>
    request<{ renderedSlides: unknown[]; warnings: string[] }>(
      `${G}/episodes/${episodeId}/dialogue-boxes/render${WAIT}`,
      { method: "POST", body: JSON.stringify(body) },
    ),

  generateFinalVideo: (
    episodeId: string,
    body: {
      transition?: string;
      transitionDurationSeconds?: number;
      kenBurns?: boolean;
      fps?: number;
      sceneDurationSeconds?: number;
      audioMood?: string;
      audioUrl?: string;
      audio?: boolean;
    },
  ) =>
    request<FinalVideoResult>(`${G}/episodes/${episodeId}/final-video${WAIT}`, {
      method: "POST",
      body: JSON.stringify(body),
    }),
};

