/**
 * Curated background-music library stored in R2.
 *
 * Layout (mood = folder name):
 *   audio/library/<mood>/<track>.mp3
 *
 * Drop royalty-free / CC0 tracks under a mood folder and they become available
 * automatically — no manifest to maintain. The final-video step matches an
 * episode's `musicTags` (plus its music prompt and category) to the closest
 * mood and picks a track deterministically per episode.
 */
export const LIBRARY_PREFIX = "audio/library/";

const AUDIO_EXTENSIONS = [
  ".mp3",
  ".m4a",
  ".aac",
  ".wav",
  ".ogg",
  ".opus",
  ".flac",
];

/** Canonical moods and the keywords that route musicTags/prompts to them. */
export const MOOD_KEYWORDS: Record<string, string[]> = {
  dramatic: [
    "dramatic",
    "drama",
    "tension",
    "intense",
    "orchestral",
    "strings",
    "emotional",
    "serial",
    "melodrama",
    "confrontation",
    "betrayal",
    "stinger",
    "cliffhanger",
    "sitar",
    "tabla",
  ],
  romantic: ["romantic", "romance", "love", "tender", "flute", "warm", "soft"],
  suspense: [
    "suspense",
    "suspenseful",
    "mystery",
    "ominous",
    "dark",
    "thriller",
    "hum",
    "heartbeat",
    "pulse",
    "distant",
  ],
  action: [
    "action",
    "fast",
    "percussion",
    "battle",
    "chase",
    "energetic",
    "driving",
    "power",
  ],
  sad: ["sad", "sorrow", "melancholy", "grief", "somber", "mournful", "tragic"],
  horror: [
    "horror",
    "scary",
    "dread",
    "creepy",
    "sinister",
    "eerie",
    "dripping",
    "metallic",
  ],
  uplifting: [
    "uplifting",
    "hopeful",
    "happy",
    "triumphant",
    "bright",
    "joyful",
    "inspiring",
  ],
  ambient: [
    "ambient",
