    "pads",
    "drone",
    "electronic",
    "background",
    "gentle",
    "chime",
    "bass",
  ],
  comedic: ["comedy", "comedic", "quirky", "playful", "funny", "light", "silly"],
};

/** Order used to break ties / fall back when no mood scores a hit. */
const MOOD_FALLBACK_ORDER = [
  "dramatic",
  "ambient",
  "suspense",
  "romantic",
  "action",
  "sad",
  "uplifting",
  "horror",
  "comedic",
];

export type LibraryTrack = { key: string; mood: string };

function isAudioFile(name: string) {
  const lower = name.toLowerCase();
  return AUDIO_EXTENSIONS.some((ext) => lower.endsWith(ext));
}

type S3ListResult = {
  contents?: { key: string }[];
  isTruncated?: boolean;
  nextContinuationToken?: string;
};

/** Lists the library grouped by mood folder. Empty map if nothing is uploaded. */
export async function listLibrary(): Promise<Map<string, string[]>> {
  const byMood = new Map<string, string[]>();
  let continuationToken: string | undefined;

  do {
    const result = (await (
      s3Client as unknown as {
        list: (options: Record<string, unknown>) => Promise<S3ListResult>;
      }
    ).list({
      prefix: LIBRARY_PREFIX,
      maxKeys: 1000,
      continuationToken,
    })) as S3ListResult;

    for (const item of result.contents ?? []) {
      const rest = item.key.slice(LIBRARY_PREFIX.length);
      const slash = rest.indexOf("/");
      if (slash <= 0) continue;

      const mood = rest.slice(0, slash).toLowerCase();
      const file = rest.slice(slash + 1);
      if (!file || file.endsWith("/") || !isAudioFile(file)) continue;

      const tracks = byMood.get(mood) ?? [];
      tracks.push(item.key);
      byMood.set(mood, tracks);
    }

    continuationToken = result.isTruncated
      ? result.nextContinuationToken
      : undefined;
  } while (continuationToken);

  return byMood;
}

/** Stable non-negative hash so track choice is deterministic per episode. */
function stableHash(value: string) {
  let hash = 5381;
  for (let i = 0; i < value.length; i += 1) {
    hash = (hash * 33) ^ value.charCodeAt(i);
  }
  return Math.abs(hash);
}

function scoreMood(mood: string, haystack: string) {
  const keywords = MOOD_KEYWORDS[mood] ?? [];
  let score = 0;
  for (const keyword of keywords) {
    if (haystack.includes(keyword)) score += 1;
  }
  return score;
}

export type SelectTrackParams = {
  episodeId: string;
  musicTags?: string[];
  musicPrompt?: string | null;
  category?: string | null;
  /** Force a specific mood folder, bypassing keyword matching. */
  mood?: string;
};

/**
 * Picks the best-matching background track for an episode, or null when the
 * library is empty. Returns the chosen mood and R2 key.
 */
export async function selectBackgroundTrack(
  params: SelectTrackParams,
): Promise<LibraryTrack | null> {
  const library = await listLibrary();
  if (library.size === 0) return null;

  const pickFromMood = (mood: string): LibraryTrack | null => {
    const tracks = library.get(mood);
    if (!tracks || tracks.length === 0) return null;
    const index = stableHash(params.episodeId) % tracks.length;
    return { key: tracks[index]!, mood };
  };

  // Explicit override wins when that mood folder exists.
  if (params.mood) {
    const forced = pickFromMood(params.mood.toLowerCase());
    if (forced) return forced;
  }

  const haystack = [
    ...(params.musicTags ?? []),
    params.musicPrompt ?? "",
    params.category ?? "",
  ]
    .join(" ")
    .toLowerCase();

  let bestMood: string | null = null;
  let bestScore = 0;
  for (const mood of library.keys()) {
    const score = scoreMood(mood, haystack);
    if (score > bestScore) {
      bestScore = score;
      bestMood = mood;
    }
  }

  if (bestMood) {
    const chosen = pickFromMood(bestMood);
    if (chosen) return chosen;
  }

  // No keyword hit: fall back to a sensible default mood that actually exists.
  for (const mood of MOOD_FALLBACK_ORDER) {
    const chosen = pickFromMood(mood);
    if (chosen) return chosen;
  }

  // Last resort: whatever mood we have.
  const firstMood = library.keys().next().value;
  return firstMood ? pickFromMood(firstMood) : null;
}

import { betterAuth } from "better-auth";
import { prismaAdapter } from "better-auth/adapters/prisma";
import { prisma } from "@directorscut/db";

/*
  The customer studio and the API are separate origins — 3002/3000 locally,
  `app.…`/`api.…` in Coolify — so the session cookie has to be readable from
  both. Setting it on the shared parent domain with `sameSite: "lax"` does
  that; the matching half is `CORS_ORIGIN` + `credentials: true` in index.ts.

  Locally both origins are `localhost`, which shares cookies by host, so the
  domain is left unset unless COOKIE_DOMAIN says otherwise.
*/
const cookieDomain = process.env.COOKIE_DOMAIN?.trim();
const trustedOrigins = process.env.CORS_ORIGIN?.split(",")
  .map((origin) => origin.trim())
  .filter(Boolean);

if (!process.env.BETTER_AUTH_SECRET) {
  throw new Error(
    "BETTER_AUTH_SECRET is required. Sessions cannot be signed without it.",
  );
}

export const auth = betterAuth({
  secret: process.env.BETTER_AUTH_SECRET,
  baseURL: process.env.BETTER_AUTH_URL,
  trustedOrigins,
  database: prismaAdapter(prisma, { provider: "postgresql" }),
  emailAndPassword: {
    enabled: true,
  },
  advanced: {
    crossSubDomainCookies: cookieDomain
      ? { enabled: true, domain: cookieDomain }
      : { enabled: false },
    defaultCookieAttributes: {
      sameSite: "lax",
      secure: process.env.NODE_ENV === "production",
    },
  },
});

export type Session = typeof auth.$Infer.Session.session;
export type AuthUser = typeof auth.$Infer.Session.user;

import type { Request, Response } from "express";
import s3Client from "@directorscut/s3";
import { prisma } from "@directorscut/db";
import { requiredString, sendFailure } from "../utils";
import { OwnershipError, requireUserId } from "../services/ownership";
import { isCharacterPortraitKey } from "../services/character-portrait";
import {
  isSceneAssetVariant,
  sceneAssetKey,
  type SceneAssetVariant,
} from "../services/scene-asset";
import { isEpisodeVideoKey } from "../services/episode-video";

/**
 * Returns a short-lived presigned URL for an R2 object key so the admin UI can
 * display generated stills/slides/renders (which are stored as bucket keys, not
 * public URLs).
 */
export async function presignAsset(req: Request, res: Response) {
  try {
    const key = requiredString(req.query.key, "key");
    const url = s3Client.presign(key, { expiresIn: 3600 });
    res.json({ key, url });
  } catch (error) {
    sendFailure(res, error);
  }
}

/**
 * Redirects an owned character portrait to a short-lived signed object URL.
 *
 * The caller supplies only a character id. The object key is resolved from an
 * ownership-scoped database query and checked against the character namespace,
 * so this route cannot be used as a general-purpose bucket-key presigner.
 */
export async function getCharacterPortrait(req: Request, res: Response) {
  try {
    const characterId = requiredString(req.params.characterId, "characterId");
    const userId = requireUserId(req);
    const character = await prisma.character.findFirst({
      where: { id: characterId, series: { userId } },
      select: { id: true, seriesId: true, assetUrl: true },
    });

    if (!character?.assetUrl || !character.seriesId) {
      throw new OwnershipError("character portrait");
    }

    if (
      !isCharacterPortraitKey({
        key: character.assetUrl,
        seriesId: character.seriesId,
        characterId: character.id,
      })
    ) {
      throw new Error("The character portrait key is outside its namespace.");
    }

    const url = s3Client.presign(character.assetUrl, { expiresIn: 900 });
    res.set("Cache-Control", "private, no-store");
    res.redirect(302, url);
  } catch (error) {
    sendFailure(res, error);
  }
}

const sceneAssetField = {
  still: "assetUrl",
  slide: "slideUrl",
  render: "renderUrl",
} as const satisfies Record<SceneAssetVariant, string>;

export async function getSceneAsset(req: Request, res: Response) {
  try {
    const sceneId = requiredString(req.params.sceneId, "sceneId");
    const variant = requiredString(req.params.variant, "variant");
    if (!isSceneAssetVariant(variant)) {
      throw new Error(`Unsupported scene asset variant "${variant}".`);
    }

    const userId = requireUserId(req);
    const scene = await prisma.scene.findFirst({
      where: { id: sceneId, episode: { series: { userId } } },
      select: {
        id: true,
        episodeId: true,
        assetUrl: true,
        slideUrl: true,
        renderUrl: true,
      },
    });
    const key = scene?.[sceneAssetField[variant]];

    if (!scene || !key) {
      throw new OwnershipError("scene asset");
    }

    if (key !== sceneAssetKey(variant, scene.episodeId, scene.id)) {
      throw new Error("The scene asset key is outside its namespace.");
    }

    const url = s3Client.presign(key, { expiresIn: 900 });
    res.set("Cache-Control", "private, no-store");
    res.redirect(302, url);
  } catch (error) {
    sendFailure(res, error);
  }
}

/** Redirects an owned final cut to a short-lived signed R2 URL. */
export async function getEpisodeFinalVideo(req: Request, res: Response) {
  try {
    const episodeId = requiredString(req.params.episodeId, "episodeId");
    const userId = requireUserId(req);
    const episode = await prisma.episode.findFirst({
      where: { id: episodeId, series: { userId } },
      select: { id: true, finalVideoUrl: true },
    });

    if (!episode?.finalVideoUrl) {
      throw new OwnershipError("episode video");
    }

    if (
      !isEpisodeVideoKey({
        key: episode.finalVideoUrl,
        episodeId: episode.id,
      })
    ) {
      throw new Error("The episode video key is outside its namespace.");
    }

    const url = s3Client.presign(episode.finalVideoUrl, { expiresIn: 900 });
    res.set("Cache-Control", "private, no-store");
    res.redirect(302, url);
  } catch (error) {
    sendFailure(res, error);
  }
}

import type { Request, Response } from "express";
import { prisma } from "@directorscut/db";
import { requiredString, sendError, sendFailure } from "../utils";
import { requireUserId } from "../services/ownership";

/**
 * Reads one account, and the only account a caller may read is their own.
 * Anything else answers 404 rather than 403, for the reason in
 * services/ownership.ts: a 403 would confirm that the id names a real user.
 */
export async function getCustomer(req: Request, res: Response) {
  try {
    const userId = requireUserId(req);
    const customerId = requiredString(req.params.id, "id");

    if (customerId !== userId) {
      sendError(res, 404, "NOT_FOUND", "No such customer.");
      return;
    }

    const customer = await prisma.user.findUnique({
      where: { id: userId },
      select: {
        id: true,
        name: true,
        email: true,
        image: true,
        createdAt: true,
      },
    });

    if (!customer) {
      sendError(res, 404, "NOT_FOUND", "No such customer.");
      return;
    }

    res.json(customer);
  } catch (error) {
    sendFailure(res, error);
  }
}

