export async function generateDialogueBoxes(req: Request, res: Response) {
  try {
    const userId = requireUserId(req);
    const episodeId = requiredString(req.params.episodeId, "episodeId");
    await assertEpisodeOwned(episodeId, userId);

    const episode = await loadEpisodeForPrompting(episodeId);

    if (!episode || !episode.series) {
      sendError(res, 404, "NOT_FOUND", "No such episode.");
      return;
    }

    const response = {
      cssSpec: createDialogueBoxCssSpec(),
      boxes: episode.scenes.flatMap((scene) =>
        scene.dialogues.map((dialogue) => ({
          dialogueId: dialogue.id,
          sceneId: scene.id,
          sceneNumber: scene.sceneNumber,
          characterId: dialogue.characterId,
          characterName: dialogue.character.name,
          text: dialogue.text,
          grid: dialogue.dialogBoxGrid,
        })),
      ),
    };

    res.json(response);
  } catch (error) {
    sendFailure(res, error);
  }
}

export async function generateDialogueGridPrompts(req: Request, res: Response) {
  try {
    const body = bodyRecord(req);
