        characters: scene.characters,
        dialogues: scene.dialogues.map((dialogue) => ({
          id: dialogue.id,
          text: dialogue.text,
          character: dialogue.character,
        })),
        grid,
      }),
    }));

    res.json({ prompts });
  } catch (error) {
    sendFailure(res, error);
  }
}

/**
 * The only handler that takes its ids from an array in the body rather than
 * from the path, so ownership is asserted over the whole batch before a single
 * row is written — one foreign id rejects the request instead of the other
 * placements landing anyway.
 */
export async function placeDialogueBoxes(req: Request, res: Response) {
  try {
    const userId = requireUserId(req);
    const body = bodyRecord(req);
    const placements = body.placements as
      | { dialogueId: string; grid: string }[]
      | undefined;

    if (!Array.isArray(placements)) {
      sendError(
        res,
        400,
        "INVALID_REQUEST",
        "A placements array is required.",
        "placements",
      );
      return;
    }

    await assertDialoguesOwned(
      placements.map((placement) => placement.dialogueId),
      userId,
    );

    await Promise.all(
      placements.map((placement) =>
        prisma.dialogue.update({
          where: { id: placement.dialogueId },
          data: { dialogBoxGrid: placement.grid },
        }),
      ),
    );

    res.json({ updated: placements.length });
  } catch (error) {
    sendFailure(res, error);
  }
}

