import { cn } from "@/lib/utils"

const copy = {
  login: {
    title: "Welcome back",
    description: "Sign in to continue your preparation.",
    submit: "Log in",
    switchText: "New to noteformula?",
    switchLabel: "Create an account",
    switchHref: "/signup",
  },
  signup: {
    title: "Create your account",
    description: "Start building a study plan that adapts to you.",
    submit: "Create account",
    switchText: "Already have an account?",
    switchLabel: "Log in",
    switchHref: "/login",
  },
} as const

const inputClassName =
  "auth-control h-11 rounded-xl border-input bg-card/50 px-3.5 text-sm text-foreground transition-[border-color,box-shadow,background-color] duration-150 placeholder:text-muted-foreground hover:bg-card/65 focus-visible:border-primary focus-visible:ring-primary/20 sm:h-10 dark:bg-card/50"

export function AuthForm({ mode }: { mode: "login" | "signup" }) {
  const action = mode === "signup" ? signupAction : loginAction
  const [state, formAction, pending] = React.useActionState(
    action,
    initialAuthActionState
  )
  const [passwordVisible, setPasswordVisible] = React.useState(false)
  const text = copy[mode]

  return (
    <div className="auth-form-enter w-full max-w-sm text-center">
      <Link
        href="/"
        aria-label="Go to noteformula home"
        className="auth-icon-surface mx-auto mb-6 flex size-10 items-center justify-center rounded-xl border border-border/70 bg-card/55 text-muted-foreground outline-none transition-[border-color,color,transform,box-shadow] duration-150 hover:border-border hover:text-foreground focus-visible:ring-3 focus-visible:ring-primary/25 active:scale-[0.96]"
      >
        <BrandMark className="text-lg" />
      </Link>

      <h1 className="font-heading text-[1.75rem] leading-tight font-semibold tracking-[-0.03em] text-foreground">
        {text.title}
      </h1>
      <p className="mt-2.5 text-sm leading-5 text-muted-foreground">{text.description}</p>

      <form action={formAction} noValidate className="mt-7 text-left">
        <FieldGroup className="gap-3">
          {mode === "signup" ? (
            <Field className="gap-1.5" data-invalid={state.fieldErrors.name ? true : undefined}>
              <FieldLabel htmlFor="name" className="sr-only">Full name</FieldLabel>
              <Input
                id="name"
                name="name"
                autoComplete="name"
                placeholder="Full name"
                minLength={2}
                maxLength={80}
                required
                aria-invalid={state.fieldErrors.name ? true : undefined}
                className={inputClassName}
              />
              {state.fieldErrors.name ? (
                <FieldError className="auth-message-enter px-1">{state.fieldErrors.name}</FieldError>
              ) : null}
            </Field>
          ) : null}

          <Field className="gap-1.5" data-invalid={state.fieldErrors.email ? true : undefined}>
            <FieldLabel htmlFor="email" className="sr-only">Email</FieldLabel>
            <Input
              id="email"
              name="email"
              type="email"
              autoComplete="email"
              placeholder="Email address"
              required
              aria-invalid={state.fieldErrors.email ? true : undefined}
              className={inputClassName}
            />
            {state.fieldErrors.email ? (
              <FieldError className="auth-message-enter px-1">{state.fieldErrors.email}</FieldError>
            ) : null}
          </Field>

          <Field className="gap-1.5" data-invalid={state.fieldErrors.password ? true : undefined}>
            <FieldLabel htmlFor="password" className="sr-only">Password</FieldLabel>
            <div className="relative">
              <Input
                id="password"
                name="password"
                type={passwordVisible ? "text" : "password"}
                autoComplete={mode === "signup" ? "new-password" : "current-password"}
                placeholder={mode === "signup" ? "Password (8 characters minimum)" : "Password"}
                minLength={8}
                maxLength={128}
                required
                aria-invalid={state.fieldErrors.password ? true : undefined}
                className={`${inputClassName} pr-11`}
              />
              <button
                type="button"
                onClick={() => setPasswordVisible((visible) => !visible)}
                className="absolute inset-y-0 right-0 flex w-11 items-center justify-center rounded-r-xl text-muted-foreground outline-none transition-[color,transform] duration-150 hover:text-foreground focus-visible:ring-3 focus-visible:ring-inset focus-visible:ring-primary/25 active:scale-[0.96]"
                aria-label={passwordVisible ? "Hide password" : "Show password"}
                aria-pressed={passwordVisible}
              >
                <span className="relative size-4.5">
                  <HugeiconsIcon
                    icon={ViewOffIcon}
                    strokeWidth={1.8}
                    className={cn(
                      "absolute inset-0 size-4.5 transition-[opacity,filter,scale] duration-300 ease-[cubic-bezier(0.2,0,0,1)]",
                      passwordVisible
                        ? "scale-100 opacity-100 blur-0"
                        : "scale-[0.25] opacity-0 blur-[4px]"
                    )}
                  />
                  <HugeiconsIcon
                    icon={EyeIcon}
                    strokeWidth={1.8}
                    className={cn(
                      "absolute inset-0 size-4.5 transition-[opacity,filter,scale] duration-300 ease-[cubic-bezier(0.2,0,0,1)]",
                      passwordVisible
                        ? "scale-[0.25] opacity-0 blur-[4px]"
                        : "scale-100 opacity-100 blur-0"
                    )}
                  />
                </span>
              </button>
            </div>
            {state.fieldErrors.password ? (
              <FieldError className="auth-message-enter px-1">{state.fieldErrors.password}</FieldError>
            ) : null}
          </Field>

          {state.formError ? (
            <p role="alert" className="auth-message-enter rounded-lg border border-destructive/25 bg-destructive/8 px-3 py-2.5 text-sm text-destructive">
              {state.formError}
            </p>
          ) : null}

          <Button
            type="submit"
            size="lg"
            disabled={pending}
            className="auth-primary-button mt-1.5 h-11 w-full rounded-xl bg-primary text-sm font-semibold text-primary-foreground transition-[background-color,box-shadow,transform] duration-150 hover:bg-primary/90 active:scale-[0.96] sm:h-10"
          >
            {pending ? <Spinner /> : null}
            {text.submit}
          </Button>
        </FieldGroup>
      </form>

      <p className="mt-6 text-sm text-muted-foreground">
        {text.switchText}{" "}
        <Link
          href={text.switchHref}
          className="rounded-sm font-medium text-foreground underline-offset-4 outline-none transition-colors duration-150 hover:text-primary hover:underline focus-visible:ring-3 focus-visible:ring-primary/25"
        >
          {text.switchLabel}
        </Link>
      </p>
    </div>
  )
}

import { redirect } from "next/navigation"
import { getSession } from "@/lib/server/session"

export async function PublicAuthGate({
  children,
}: {
  children: React.ReactNode
}) {
  const session = await getSession()

  if (session) {
    redirect("/")
  }

  return children
}

