const variants = materialVariantSchema.options
const filterValues = ["all", ...variants] as const
type VariantFilter = (typeof filterValues)[number]

/** `ToggleGroup` reports a plain `string[]`, and deselecting gives an empty one. */
function toVariantFilter(value: string | undefined): VariantFilter {
  return filterValues.find((candidate) => candidate === value) ?? "all"
}

const libraryParams = {
  q: parseAsString.withDefault(""),
  variant: parseAsStringLiteral(filterValues).withDefault("all"),
  saved: parseAsBoolean.withDefault(false),
}

export function MaterialsLibrary() {
  const { data, isPending, error, refetch } = useMaterialLibrary()
  const [filters, setFilters] = useQueryStates(libraryParams, { history: "replace" })
  const [view, setView] = useQueryState("view", viewModeParser)

  if (isPending) {
    return (
      <>
        <StudyHeaderSkeleton />
        <CardGridSkeleton cards={4} />
      </>
    )
  }

  if (error) {
    return (
      <div className="p-4 sm:p-8">
        <QueryError
          message={errorMessage(error, "We could not load your materials.")}
          onRetry={() => refetch()}
        />
      </div>
    )
  }

  const query = filters.q.trim().toLowerCase()
  const materials = data.filter((material) => {
    if (filters.saved && !material.saved) return false
    if (filters.variant !== "all" && !material.variants.includes(filters.variant)) return false
    if (!query) return true
    return [material.title, material.subjectName, material.chapterName, material.topicName]
      .filter(Boolean)
      .some((field) => field!.toLowerCase().includes(query))
  })

  const isFiltered = query.length > 0 || filters.variant !== "all" || filters.saved

  return (
    <>
      <StudyPageHeader
        title="Your materials"
        description="Every set of notes generated for your syllabus. Saving one keeps it here even after the chapter is done."
        actions={
          <ButtonLink href="/study" variant="outline">
            Browse the syllabus
          </ButtonLink>
        }
      />

      <div className="space-y-6 px-4 py-6 sm:px-8">
        <SectionHeading
          title={`${materials.length} ${materials.length === 1 ? "material" : "materials"}`}
          description="Most recently opened first."
          action={<ViewToggle value={view} onChange={setView} />}
        />

        <div className="flex flex-wrap items-center gap-3">
          <InputGroup className="w-full sm:w-72">
            <InputGroupAddon>
              <HugeiconsIcon icon={Search01Icon} strokeWidth={2} />
            </InputGroupAddon>
            <InputGroupInput
              value={filters.q}
              onChange={(event) => setFilters({ q: event.target.value })}
              placeholder="Search by chapter or subject"
              aria-label="Search your materials"
            />
          </InputGroup>

          {/* Its own scroll container: six labels overflow a narrow screen, and
              without this the whole page scrolled sideways, header included. */}
          <div className="-mx-1 min-w-0 max-w-full flex-1 overflow-x-auto px-1 pb-1">
            <ToggleGroup
              value={[filters.variant]}
              onValueChange={(next) => setFilters({ variant: toVariantFilter(next[0]) })}
              aria-label="Filter by material type"
              variant="outline"
              size="sm"
              spacing={0}
            >
              <ToggleGroupItem value="all">All</ToggleGroupItem>
              {variants.map((variant) => (
                <ToggleGroupItem key={variant} value={variant}>
                  {MATERIAL_VARIANT_LABELS[variant]}
                </ToggleGroupItem>
              ))}
            </ToggleGroup>
          </div>

          <Toggle
            pressed={filters.saved}
            onPressedChange={(pressed) => setFilters({ saved: pressed })}
            variant="outline"
            size="sm"
          >
            Saved only
          </Toggle>
        </div>

        {materials.length === 0 ? (
          isFiltered ? (
            <StudyEmpty
              illustration={<NoResultsIllustration />}
              title="Nothing matches those filters"
              description="Try a different material type, or clear the search to see everything in your library."
            >
              <Button
                variant="outline"
                size="sm"
                onClick={() => setFilters({ q: "", variant: "all", saved: false })}
              >
                Clear filters
              </Button>
            </StudyEmpty>
          ) : (
            <StudyEmpty
              illustration={<MaterialIllustration />}
              title="No materials yet"
              description="Notes are generated per chapter as you study. Open a chapter from the syllabus explorer and the material for it will land here."
            >
              <ButtonLink href="/study" size="sm">
                Open the syllabus
              </ButtonLink>
            </StudyEmpty>
          )
        ) : view === "block" ? (
          <div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3">
            {materials.map((material) => (
              <MaterialCard key={material.id} material={material} />
            ))}
          </div>
        ) : (
          <div className="divide-y rounded-xl ring-1 ring-foreground/10">
            {materials.map((material) => (
              <MaterialRow
                key={material.id}
                material={material}
                lastOpened={lastOpenedLabel(material.lastOpenedAt)}
              />
            ))}
          </div>
        )}
      </div>
    </>
  )
}

