export function QuestionLibraryCard({ item, compact = false }: { item: QuestionLibraryItem; compact?: boolean }) {
  const router = useRouter()
  const save = useSetQuestionSaved()
  const create = useCreatePracticeSession()
  const { question } = item
  const baseConfig = { subjectId: question.subjectId, chapterId: question.chapterId, topicIds: question.topicIds, questionType: question.questionType, difficulty: "adaptive" as const, questionCount: 1, mode: "practice" as const, examStyle: "jee_main" as const, balance: "balanced" as const }
  async function start(kind: "built" | "mistakes" | "similar") {
    const session = await create.mutateAsync({
      kind,
      requestId: createClientId(),
      questionIds: kind === "built" || kind === "mistakes" ? [question.id] : undefined,
      referenceQuestionId: kind === "similar" ? question.id : undefined,
      // Similar practice ranks same-type questions higher, but must keep the
      // pool mixed so a reference does not exclude every useful peer before
      // ranking can happen.
      config: {
        ...baseConfig,
        questionType: kind === "similar" ? "mixed" : baseConfig.questionType,
        questionCount: 5,
      },
    })
    router.push(`/practice/${session.id}?question=0`)
  }
  async function toggleSaved() {
    await save.mutateAsync({ questionId: question.id, saved: !item.isSaved })
    toast.add({ title: item.isSaved ? "Removed from saved questions" : "Saved to your question library", type: "success" })
  }
  return (
    <Card><CardContent className={cn("space-y-4", compact && "py-4")}>
      <div className="flex flex-wrap items-start justify-between gap-3"><div className="min-w-0 flex-1"><p className="mb-2 text-xs text-muted-foreground">{question.subjectName} · {question.chapterName}{question.topicNames[0] ? ` · ${question.topicNames[0]}` : ""}</p><h2 className="font-heading font-semibold leading-6">{question.prompt}</h2></div><Button variant="ghost" size="sm" onClick={toggleSaved} disabled={save.isPending}>{item.isSaved ? <HugeiconsIcon icon={BookmarkCheck02Icon} strokeWidth={2} data-icon="inline-start" /> : <HugeiconsIcon icon={Bookmark03Icon} strokeWidth={2} data-icon="inline-start" />}{item.isSaved ? "Saved" : "Save"}</Button></div>
      <div className="flex flex-wrap gap-2"><QuestionTypeChip type={question.questionType} /><DifficultyChip level={question.difficulty} /><QuestionSourceChip source={question.sourceType} /><PracticeReviewChip status={question.reviewStatus} /></div>
      {!compact ? <details className="rounded-lg border px-4 py-3"><summary className="cursor-pointer text-sm font-medium">Show answer and solution</summary><div className="mt-3 space-y-3 border-t pt-3"><div><p className="text-xs font-medium tracking-wide text-muted-foreground uppercase">Answer</p><p className="mt-1 text-sm">{correctAnswerText(question)}</p></div><p className="text-sm leading-6 text-muted-foreground">{question.solution}</p></div></details> : null}
      <div className="flex flex-wrap items-center gap-2"><Button onClick={() => start(item.isMistake ? "mistakes" : "built")} disabled={create.isPending} size="sm"><HugeiconsIcon icon={RepeatIcon} strokeWidth={2} data-icon="inline-start" />Retry</Button><Button variant="outline" size="sm" onClick={() => start("similar")} disabled={create.isPending}><HugeiconsIcon icon={Target02Icon} strokeWidth={2} data-icon="inline-start" />Practise similar</Button><ButtonLink href={`/ask?question=${question.id}`} variant="outline" size="sm"><HugeiconsIcon icon={AiMagicIcon} strokeWidth={2} data-icon="inline-start" />Ask AI</ButtonLink><QuestionReportDialog questionId={question.id} /><span className="ms-auto text-xs text-muted-foreground tabular-nums">{item.attemptCount} {item.attemptCount === 1 ? "attempt" : "attempts"}</span></div>
      {create.error ? <p role="alert" className="text-sm text-destructive">{create.error.message}</p> : null}
    </CardContent></Card>
  )
}

