export function QuestionLibraryView({ kind }: { kind: "questions" | "mistakes" }) {
  const router = useRouter()
  const [filters, setFilters] = useQueryStates(questionLibraryParams, { history: "replace" })
  const [view, setView] = useQueryState("view", viewModeParser)
  const serverFilters: PracticeLibraryQuery = {
    search: filters.q.trim() || undefined,
    subjectId: filters.subject === "all" ? undefined : filters.subject,
    chapterId: filters.chapter === "all" ? undefined : filters.chapter,
    topicId: filters.topic === "all" ? undefined : filters.topic,
    questionType: filters.type === "all" ? undefined : filters.type,
    difficulty: filters.difficulty === "all" ? undefined : filters.difficulty,
    tab: kind === "questions" && filters.tab !== "all" ? filters.tab : undefined,
    pageSize: 20,
  }
  // Filters and counts are resolved by the server. Only the active collection
  // is requested, and each page contains at most 20 answer-bearing records.
  const libraryQuery = useQuestionLibrary(serverFilters, kind === "questions")
  const mistakesQuery = useMistakeBook(serverFilters, kind === "mistakes")
  const syllabus = useActiveSyllabus()
  const create = useCreatePracticeSession()
  const query = kind === "mistakes" ? mistakesQuery : libraryQuery
  if (query.isPending || syllabus.isPending) return <QuestionLibrarySkeleton />
  if (query.error) return <div className="p-4 sm:p-8"><QueryError message={errorMessage(query.error, kind === "mistakes" ? "We could not load your Mistake Book." : "We could not load your question library.")} onRetry={() => query.refetch()} /></div>
  if (syllabus.error) return <div className="p-4 sm:p-8"><QueryError message={errorMessage(syllabus.error, "We could not load your active syllabus.")} onRetry={() => syllabus.refetch()} /></div>
  const items = query.data.pages.flatMap((page) => page.items)
  const totalCount = query.data.pages[0]?.totalCount ?? 0
  const subjectOptions = (syllabus.data?.subjects ?? []).map((subject) => [subject.id, subject.name] as const)
  const isFiltered = filters.q !== "" || filters.subject !== "all" || filters.chapter !== "all" || filters.topic !== "all" || filters.difficulty !== "all" || filters.type !== "all" || filters.tab !== "all"
  async function startMistakeTest() {
    const ids = items.slice(0, 20).map((item) => item.question.id)
    const session = await create.mutateAsync({ kind: "mistakes", questionIds: ids, requestId: createClientId(), config: { subjectId: filters.subject, chapterId: filters.chapter, topicIds: filters.topic === "all" ? [] : [filters.topic], questionType: "mixed", difficulty: "adaptive", questionCount: ids.length, mode: "practice", examStyle: "jee_main", balance: "balanced" } })
    router.push(`/practice/${session.id}?question=0`)
  }
  return (
    <>
      <StudyPageHeader crumbs={[{ label: "Library", href: "/library" }, { label: kind === "mistakes" ? "Mistake Book" : "Questions" }]} title={kind === "mistakes" ? "Mistake Book" : "Your question library"} description={kind === "mistakes" ? "Every question you missed stays here with its solution, retry path and tutor context." : "Saved, attempted and recommended questions in one personal bank, with provenance visible."} actions={kind === "mistakes" ? <Button onClick={startMistakeTest} disabled={items.length === 0 || create.isPending}><HugeiconsIcon icon={Target02Icon} strokeWidth={2} data-icon="inline-start" />{create.isPending ? "Building test…" : `Create test from ${Math.min(items.length, 20)} mistake${Math.min(items.length, 20) === 1 ? "" : "s"}`}</Button> : <ButtonLink href="/practice" variant="outline">Build practice</ButtonLink>} />
      <div className="space-y-6 px-4 py-6 sm:px-8">
        {kind === "questions" ? <Tabs value={filters.tab} onValueChange={(value) => setFilters({ tab: value === "saved" || value === "attempted" ? value : "all" })}><TabsList><TabsTrigger value="all">All</TabsTrigger><TabsTrigger value="saved">Saved</TabsTrigger><TabsTrigger value="attempted">Attempted</TabsTrigger></TabsList></Tabs> : null}
        <div className="flex flex-wrap items-center gap-3"><InputGroup className="w-full sm:w-72"><InputGroupAddon><HugeiconsIcon icon={Search01Icon} strokeWidth={2} /></InputGroupAddon><InputGroupInput value={filters.q} onChange={(event) => setFilters({ q: event.target.value })} placeholder="Search questions" aria-label="Search questions" /></InputGroup><NativeSelect value={filters.subject} onChange={(event) => setFilters({ subject: event.target.value, chapter: "all", topic: "all" })} aria-label="Filter by subject"><NativeSelectOption value="all">All subjects</NativeSelectOption>{subjectOptions.map(([id, name]) => <NativeSelectOption key={id} value={id}>{name}</NativeSelectOption>)}</NativeSelect><NativeSelect value={filters.difficulty} onChange={(event) => setFilters({ difficulty: event.target.value === "easy" || event.target.value === "medium" || event.target.value === "hard" ? event.target.value : "all" })} aria-label="Filter by difficulty"><NativeSelectOption value="all">All difficulties</NativeSelectOption><NativeSelectOption value="easy">Easy</NativeSelectOption><NativeSelectOption value="medium">Medium</NativeSelectOption><NativeSelectOption value="hard">Hard</NativeSelectOption></NativeSelect><NativeSelect value={filters.type} onChange={(event) => { const next = questionTypeSchema.options.find((type) => type === event.target.value) ?? "all"; setFilters({ type: next }) }} aria-label="Filter by question type"><NativeSelectOption value="all">All types</NativeSelectOption>{questionTypeSchema.options.map((type) => <NativeSelectOption key={type} value={type}>{QUESTION_TYPE_LABELS[type]}</NativeSelectOption>)}</NativeSelect></div>
        <SectionHeading title={`${totalCount} ${totalCount === 1 ? "question" : "questions"}`} description={kind === "mistakes" ? "Incorrect questions stay here after a successful retry, so revision history is not erased." : "Question provenance and review status are always shown."} action={<ViewToggle value={view} onChange={setView} />} />
        {kind === "mistakes" && totalCount > 20 ? <p className="text-sm text-muted-foreground">A test uses the first 20 mistakes currently loaded. Keep the filters narrow to practise a different slice.</p> : null}
        {items.length === 0 ? isFiltered ? <StudyEmpty illustration={<NoResultsIllustration />} title="Nothing matches those filters" description="Clear the filters to return to the full question set."><Button variant="outline" onClick={() => setFilters({ q: "", subject: "all", chapter: "all", topic: "all", difficulty: "all", type: "all", tab: "all" })}>Clear filters</Button></StudyEmpty> : <StudyEmpty illustration={kind === "mistakes" ? <MistakesIllustration /> : <QuestionsIllustration />} title={kind === "mistakes" ? "No mistakes yet" : "No questions here yet"} description={kind === "mistakes" ? "Incorrect answers are added automatically. Start a practice session to find what deserves another pass." : "Save a question during practice and it will appear here."}><ButtonLink href="/practice">Start practice</ButtonLink></StudyEmpty> : <div className={cn("gap-4", view === "block" ? "grid xl:grid-cols-2" : "space-y-4")}>{items.map((item) => <QuestionLibraryCard key={item.question.id} item={item} compact={view === "list"} />)}</div>}
        {query.hasNextPage ? <div className="flex justify-center"><Button variant="outline" onClick={() => query.fetchNextPage()} disabled={query.isFetchingNextPage}>{query.isFetchingNextPage ? "Loading more…" : `Load more (${items.length} of ${totalCount})`}</Button></div> : null}
        <p role="status" aria-live="polite" className="sr-only">{query.isFetchingNextPage ? "Loading more questions" : `${items.length} of ${totalCount} questions loaded`}</p>
        {create.error ? <p role="alert" className="text-sm text-destructive">{errorMessage(create.error, "We could not build that Mistake Book test.")}</p> : null}
      </div>
    </>
  )
}

import { sleep } from "workflow"
import { assessmentAutoSubmitCheckpointStep } from "@/workflows/assessment-auto-submit/steps"

export async function autoSubmitAssessment(attemptId: string, dispatchToken: string) {
  "use workflow"

  let checkpoint = await assessmentAutoSubmitCheckpointStep(attemptId, dispatchToken)
  while (checkpoint.state === "waiting") {
    await sleep(new Date(checkpoint.wakeAt))
    checkpoint = await assessmentAutoSubmitCheckpointStep(attemptId, dispatchToken)
  }

  return { attemptId, state: checkpoint.state }
}

