}

import {
  completeMaterialJobStep,
  failMaterialJobStep,
  generateMaterialEditionStep,
  persistMaterialEditionStep,
  prepareMaterialJobStep,
  updateMaterialProgressStep,
} from "@/workflows/material-generation/steps"

export async function generateStudyMaterial(jobId: string) {
  "use workflow"

  try {
    const prepared = await prepareMaterialJobStep(jobId)
    let completed = 0

    for (const target of prepared.targets) {
      for (const variant of prepared.variants) {
        await updateMaterialProgressStep(
          jobId,
          completed,
          `Generating ${variant} material for ${target.topicName ?? target.chapterName}`
        )
        const generated = await generateMaterialEditionStep(jobId, {
          ...target,
          variant,
        })
        await persistMaterialEditionStep(jobId, target, variant, generated)
        completed += 1
        await updateMaterialProgressStep(
          jobId,
          completed,
          `Stored ${variant} material for ${target.topicName ?? target.chapterName}`
        )
      }
    }

    await completeMaterialJobStep(jobId)
    return { jobId, state: "succeeded" as const }
  } catch (error) {
    const reason =
      error instanceof Error
        ? error.message
        : typeof error === "object" &&
            error !== null &&
            "message" in error &&
            typeof error.message === "string"
          ? error.message
          : "Material generation failed."
    await failMaterialJobStep(jobId, reason)
    return { jobId, state: "failed" as const }
  }
}

import {
  collectSourcesStep,
