    const reason =
      error instanceof Error
        ? error.message
        : typeof error === "object" &&
            error !== null &&
            "message" in error &&
            typeof error.message === "string"
          ? error.message
          : "Research workflow failed."
    await failResearchStep(jobId, reason)
    return { jobId, state: "failed" as const }
  }
}

import {
  completeQuestionGenerationStep,
  countQuestionGenerationStep,
  failQuestionGenerationStep,
  generateQuestionBatchStep,
  persistQuestionBatchStep,
  prepareQuestionGenerationStep,
  progressQuestionGenerationStep,
} from "@/workflows/question-generation/steps"

// Bounded batch size (workflow-safe constant; steps stay opaque boundaries).
const QUESTION_BATCH_SIZE = 5

export async function generateQuestions(jobId: string, dispatchToken: string) {
  "use workflow"

  try {
    const prepared = await prepareQuestionGenerationStep(jobId, dispatchToken)
    let completed = prepared.requestedCount - prepared.remaining

    while (completed < prepared.requestedCount) {
      const batchSize = Math.min(QUESTION_BATCH_SIZE, prepared.requestedCount - completed)
      await progressQuestionGenerationStep(
        jobId,
        dispatchToken,
        completed,
        `Generating questions ${completed + 1}–${completed + batchSize}`
      )
      const generated = await generateQuestionBatchStep(
        jobId,
        dispatchToken,
        prepared.scope,
        {
          questionType: prepared.config.questionType,
          difficulty: prepared.config.difficulty,
          balance: prepared.config.balance,
          examStyle: prepared.config.examStyle,
          count: batchSize,
          startOrdinal: completed,
        }
      )
      await persistQuestionBatchStep(jobId, prepared.scope, dispatchToken, {
        ...generated,
        startOrdinal: completed,
      })
      // Recount persisted questions so a resumed run never duplicates the
      // (job, ordinal) pairs that were already stored.
      completed = await countQuestionGenerationStep(jobId)
      await progressQuestionGenerationStep(
        jobId,
        dispatchToken,
        completed,
        `Stored ${completed} of ${prepared.requestedCount} questions`
      )
    }

    await completeQuestionGenerationStep(jobId, dispatchToken)
    return { jobId, state: "succeeded" as const }
  } catch (error) {
    const reason =
      error instanceof Error
        ? error.message
        : typeof error === "object" &&
            error !== null &&
            "message" in error &&
            typeof error.message === "string"
          ? error.message
          : "Question generation failed."
    await failQuestionGenerationStep(jobId, dispatchToken, reason)
    return { jobId, state: "failed" as const }
  }
}

